index 5becd89..9b193b7 100644
--- a/src/ffi/object.cc
+++ b/src/ffi/object.cc
@@ -220,6 +220,14 @@ class TypeTable {

   void RegisterTypeExtraInfo(int32_t type_index, const TVMFFITypeExtraInfo* extra_info) {
